**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int freq[10] = {0};
    while (plik >> n) {
        freq[n % 10]++;
    }

    cout << "a) Czestotliwosc ostatnich cyfr:" << endl;
    for (int i = 0; i < 10; i++) {
        cout << "   " << i << ": " << freq[i] << endl;
    }

    // b) najczestsza
    int maxFreq = 0, maxCyfra = 0;
    for (int i = 0; i < 10; i++) {
        if (freq[i] > maxFreq) {
            maxFreq = freq[i];
            maxCyfra = i;
        }
    }
    cout << "b) Najczestsza ostatnia cyfra: " << maxCyfra << " (" << maxFreq << " razy)" << endl;

    // c) najrzadsza (wystepujaca)
    int minFreq = 1000000, minCyfra = 0;
    for (int i = 0; i < 10; i++) {
        if (freq[i] > 0 && freq[i] < minFreq) {
            minFreq = freq[i];
            minCyfra = i;
        }
    }
    cout << "c) Najrzadsza (wystepujaca): " << minCyfra << " (" << minFreq << " raz)" << endl;
    return 0;
}
```

**Wyjasnienie**: Tablica `freq[10]` zlicza wystapienia kazdej ostatniej cyfry. Dwa przeszukania: jedno dla maksimum (najczestsza), drugie dla minimum wsrod niezerowych (najrzadsza wystepujaca).

Weryfikacja:
- 123%10=3, 456%10=6, 789%10=9, 234%10=4, 567%10=7, 891%10=1, 243%10=3, 576%10=6, 819%10=9, 132%10=2
- freq: [0]=0, [1]=1, [2]=1, [3]=2, [4]=1, [5]=0, [6]=2, [7]=1, [8]=0, [9]=2
- Najczestsza: cyfra 3 z freq=2 (iteracja od 0, 3 jest pierwsza z freq=2)
- Najrzadsza (>0): cyfra 1 z freq=1 (iteracja od 0, 1 jest pierwsza z freq=1)
